def _index(c):
    if type(c) != type('') or len(c) != 1:
        raise 'TypeError: a single Unicode character is required'
    n = ord(c)
    if n > 255:
        raise 'NotImplementedError: unicodedata tables end at Latin-1'
    return n

def category(c):
    return _categories[_index(c)]

def name(c, default=None):
    answer = _names[_index(c)]
    if answer != '':
        return answer
    if default is not None:
        return default
    raise 'ValueError: no such name'

def lookup(name):
    folded = ''
    for letter in name:
        if letter >= 'a' and letter <= 'z':
            letter = chr(ord(letter) - 32)
        folded += letter
    name = folded
    for i in range(256):
        if _names[i] != '' and _names[i] == name:
            return chr(i)
    raise 'KeyError: Unicode name is absent from the Latin-1 table'

def normalize(form, text):
    if form not in _forms:
        raise 'ValueError: invalid normalization form'
    result = ''
    for c in text:
        result += _forms[form][_index(c)]
    # Adjacent combining marks need canonical ordering and composition.
    # Latin-1 input has no such marks; its decompositions do.
    return result
